import{_ as t,o,c as a,ah as s}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"SMS & WhatsApp","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/sms-whatsapp.md","filePath":"src/en/guide/admin/sms-whatsapp.md"}'),n={name:"en/guide/admin/sms-whatsapp.md"};function i(r,e,h,p,l,d){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="sms-whatsapp" tabindex="-1">SMS &amp; WhatsApp <a class="header-anchor" href="#sms-whatsapp" aria-label="Permalink to &quot;SMS &amp; WhatsApp&quot;">​</a></h1><p>Notifications to families arrive in the app and by e-mail. With this option, some of them can also go out <strong>by SMS or on WhatsApp</strong>, to the phone of the parents who gave their number. This helps with families who rarely read their e-mails.</p><p>The page opens from <strong>Administration → SMS &amp; WhatsApp</strong>. Only administrators see it, and only if your licence includes the <strong>Family relations</strong> module.</p><h2 id="an-operator-and-credits" tabindex="-1">An operator, and credits <a class="header-anchor" href="#an-operator-and-credits" aria-label="Permalink to &quot;An operator, and credits&quot;">​</a></h2><p>Messages go through an SMS or WhatsApp operator. Each message uses a credit bought from that operator. Credits are not included in the ERA licence: they are bought separately, on quote. Contact edPage to switch the option on.</p><p>As long as no operator is connected, the page shows <strong>No operator</strong>: families are still notified in the app and by e-mail, as usual.</p><div class="info custom-block"><p class="custom-block-title">Schools hosted on Era Admission</p><p>The option is not yet offered to schools hosted on the shared platform. For now it is for installations dedicated to one school.</p></div><h3 id="pilot-mode" tabindex="-1">Pilot mode <a class="header-anchor" href="#pilot-mode" aria-label="Permalink to &quot;Pilot mode&quot;">​</a></h3><p>Before the operator is chosen, edPage can switch on a <strong>pilot mode</strong>. No message really goes out: each one is written to the application log. Everything else works as with an operator (who receives what, the month&#39;s count). Use it to choose the notifications to send and to check that parents have entered their number.</p><h2 id="choosing-what-goes-to-the-phone" tabindex="-1">Choosing what goes to the phone <a class="header-anchor" href="#choosing-what-goes-to-the-phone" aria-label="Permalink to &quot;Choosing what goes to the phone&quot;">​</a></h2><ol><li>If the operator offers both, choose <strong>Send by</strong>: SMS or WhatsApp.</li><li>Under <strong>Notifications sent</strong>, tick the ones that also go to the phone: unjustified absence, report card published, payment recorded, and so on. Only notifications meant for families are offered: staff notifications never go out by SMS.</li><li>Click <strong>Save</strong>.</li></ol><p>By default, none is ticked. Each message costs a credit, so keep the ones that really matter to families.</p><p>The message carries the notification&#39;s title and text, in the language the parent chose. An SMS is capped at 306 characters, a WhatsApp message at 1,000: anything longer is cut.</p><h2 id="who-receives-the-messages" tabindex="-1">Who receives the messages <a class="header-anchor" href="#who-receives-the-messages" aria-label="Permalink to &quot;Who receives the messages&quot;">​</a></h2><p>A parent receives a notification on their phone when all three are true:</p><ul><li>the school sends that kind of notification (box ticked above);</li><li>the parent has a <strong>phone number</strong> on their account;</li><li>they have not turned off the phone copy for that kind, in their preferences.</li></ul><p>The number comes from two places:</p><ul><li><strong>the application dossier</strong>: when an admission is approved, the guardian&#39;s number is copied to their parent account, unless they already had one;</li><li><strong>the parent themselves</strong>, in <strong>Settings → Profile</strong> (see <a href="/era-guide/en/guide/prise-en-main.html#account-settings">Getting started</a>).</li></ul><p>An administrator can also enter or correct it from the user&#39;s record, in <a href="/era-guide/en/guide/admin/personnel-utilisateurs.html">Staff and user accounts</a>. Numbers are written with the country code (for example <code>+228 90 11 22 33</code>). Without one, Togo&#39;s (+228) is added.</p><h2 id="following-what-was-sent" tabindex="-1">Following what was sent <a class="header-anchor" href="#following-what-was-sent" aria-label="Permalink to &quot;Following what was sent&quot;">​</a></h2><p>The bottom of the page shows how many messages went out this month, and how many the operator refused (credit used up, invalid number...). The last 20 messages are listed with the date, the recipient, their number, the notification and the status <strong>Sent</strong> or <strong>Refused</strong>. Hover over a <strong>Refused</strong> status to see the reason the operator gave.</p><p>A refused message is not sent again. The notification itself did reach the app and, depending on the parent&#39;s preferences, their e-mail.</p><p>This log is erased after 13 months.</p>',23)])])}const m=t(n,[["render",i]]);export{g as __pageData,m as default};
